method find_closest_elements(numbers: seq<real>) returns (a: real, b: real)
    requires |numbers| >= 2
    requires forall i, j :: 0 <= i < j < |numbers| ==> numbers[i] != numbers[j]
    ensures a <= b
    ensures exists i, j :: 0 <= i < j < |numbers| && (a == numbers[i] && b == numbers[j] || a == numbers[j] && b == numbers[i])
    ensures forall x, y :: (x in numbers && y in numbers && x != y) ==> abs(a - b) <= abs(x - y)
